export type OceanMode = 'surface' | 'underwater';

export type OceanVariable =
  | 'temperature'
  | 'salinity'
  | 'current'
  | 'chlorophyll';

export interface OceanParameters {
  temperature: number; // °C (0 - 35)
  salinity: number; // PSU (10 - 40)
  currentSpeed: number; // m/s (0 - 5)
  depth: number; // meters (0 - 5000)
  chlorophyll: number; // mg/m³ (0 - 10)
}

export interface OceanDepthPoint {
  id: string;
  latitude: number;
  longitude: number;
  depth: number;
  temperature: number;
  salinity: number;
}

export interface SpatialPoint {
  latitude: number;
  longitude: number;
  depth: number;
}

export interface VelocityVector {
  u: number;
  v: number;
  w: number;
}

export interface SpatialFieldValue {
  temperature: number;
  salinity: number;
  chlorophyll: number;
  velocity: VelocityVector;
}

export interface ArgoNode {
  depth: number;
  temperature: number;
  salinity: number;
  pressure?: number;
}

export interface ArgoProfile {
  id: string;
  name: string;
  stationCode: string;
  latitude: number;
  longitude: number;
  timestamp: string;
  nodes: ArgoNode[];
}

export interface GliderWaypoint {
  latitude: number;
  longitude: number;
  depth: number;
  timestamp: string;
  temperature: number;
  salinity: number;
}

export interface GliderTrajectory {
  id: string;
  name: string;
  mission: string;
  waypoints: GliderWaypoint[];
}

export type UnderwaterRegionId =
  | 'bay-of-bengal'
  | 'arabian-sea'
  | 'bay-of-bengal'
  | 'andaman-sea'
  | 'laccadive-sea'
  | 'java-sea'
  | 'southern-ocean';

export type OceanDomainId =
  | 'indian-ocean'
  | 'southern-ocean';

export interface UnderwaterRegionDefinition {
  id: UnderwaterRegionId;
  name: string;
  label: string;
  description: string;
  boundsLabel: string;
  west: number;
  east: number;
  south: number;
  north: number;
  depthMin: number;
  depthMax: number;
  /**
   * [longitude, latitude]
   *
   * Source: IHO Sea Areas v3.
   * Used as the source of truth for the region outline,
   * grid clipping and 3D mesh footprint.
   */
  footprint: [number, number][];
}

export interface OceanDomainDefinition {
  id: OceanDomainId;
  name: string;
  label: string;
  description: string;
  footprint: [number, number][];
  children: UnderwaterRegionId[];
}

export interface UnderwaterRegionPolygon {
  longitude: number;
  latitude: number;
}

export type UnderwaterRegion = UnderwaterRegionDefinition;

export interface UnderwaterDataPoint {
  id: string;
  latitude: number;
  longitude: number;
  depth: number;
  value: number;
  temperature: number;
  salinity: number;
  chlorophyll?: number;
  velocity?: { u: number; v: number; w?: number };
}

export interface UnderwaterCurrentVector {
  latitude: number;
  longitude: number;
  depth: number;
  u: number;
  v: number;
  speed: number;
  angle: number;
}

export interface UnderwaterRegionQuery {
  regionId: UnderwaterRegionId;
  depth: number;
  variable: OceanVariable;
}

export interface UnderwaterRegionData {
  regionId: UnderwaterRegionId;
  depth: number;
  variable: OceanVariable;
  timestamp: string;
  points: UnderwaterDataPoint[];
  currents: UnderwaterCurrentVector[];
}

